INSERT INTO `wp_term_taxonomy` (`term_taxonomy_id`, `term_id`, `taxonomy`, `description`, `parent`, `count`) VALUES
(1, 1, 'category', '', 0, 0),
(60, 60, 'sewing_machine_category', 'Embroidery Sewing Machines with high-speed stitching, precision designs and advanced features. Ideal for boutiques, tailors and professional embroidery work.', 0, 3),
(61, 61, 'sewing_machine_category', 'Shop Heavy Duty Sewing Machines for tough fabrics and continuous use. Powerful motor, durable body, high-speed stitching and perfect for professional tailors.', 0, 9),
(62, 62, 'sewing_machine_category', 'Industrial Sewing Machines built for high-speed, continuous stitching on heavy fabrics. Durable, powerful and ideal for factories, workshops and tailors.', 0, 6),
(63, 63, 'sewing_machine_category', 'Manual Sewing Machines with smooth operation, strong build and reliable stitching. Perfect for beginners, households, tailors and everyday sewing needs.', 0, 1),
(64, 64, 'sewing_machine_category', 'Overlock/Serger Machines for clean edges, fast stitching and professional finishing. Ideal for boutiques, tailors and garment units working with any fabric.', 0, 1),
(65, 65, 'air_cooler_category', 'High-performance Desert Air Coolers designed for maximum cooling, large coverage and strong airflow. Perfect for homes, halls, factories and workshops.', 0, 2),
(66, 66, 'air_cooler_category', 'Industrial Air Coolers with powerful airflow, heavy-duty motors and large coverage. Ideal for factories, warehouses, workshops and high-temperature areas.', 0, 4),
(67, 67, 'air_cooler_category', 'Mini/Portable Air Coolers with compact design, easy mobility and efficient cooling. Perfect for desks, small rooms, offices and personal cooling anywhere.', 0, 1),
(68, 68, 'air_cooler_category', 'Shop Personal Air Coolers for quick, focused cooling. Lightweight, energy-saving and ideal for desks, small rooms, workstations and daily use.', 0, 9),
(69, 69, 'air_cooler_category', 'Shop Tower Air Coolers offering strong air delivery, low noise and energy-efficient cooling. Perfect for living rooms, bedrooms and modern home spaces.', 0, 3),
(72, 72, 'service_category', 'Get quick and trusted Sewing Machine Repair services. We fix industrial, domestic and embroidery machines with quality parts and skilled technicians.', 0, 1),
(73, 73, 'service_category', 'Expert Men’s Tailoring services for suits, shirts, pants and formal wear. Perfect fit, premium fabrics, and personalized designs for every occasion.', 0, 2),
(119, 119, 'accessory_category', 'Upgrade your sewing machine with high-quality accessories designed for smoother stitching, greater accuracy, and better project results.', 0, 15),
(120, 120, 'accessory_category', 'Enhance your cooling performance with air cooler accessories designed for better airflow, improved efficiency, and long-lasting operation.', 0, 9),
